using MediatR; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using VetCommission.Application.Features.ProcedureCategories; using VetCommission.WebApi.Auth; using VetCommission.WebApi.Extensions;
namespace VetCommission.WebApi.Controllers;
[ApiController,Route("api/categorias-procedimentos"),Authorize(Policy=AuthorizationPolicyNames.ProcedureCategoriesManage)] public sealed class ProcedureCategoriesController(IMediator mediator):ControllerBase{[HttpGet("{id:guid}")]public async Task<IActionResult> Get(Guid id,CancellationToken c)=>(await mediator.Send(new GetProcedureCategoryQuery(id),c)).ToActionResult(this);[HttpGet]public async Task<IActionResult> List([FromQuery]int page=1,[FromQuery]int pageSize=20,[FromQuery]string? busca=null,CancellationToken c=default)=>(await mediator.Send(new ListProcedureCategoriesQuery(page,pageSize,busca),c)).ToActionResult(this);[HttpPost]public async Task<IActionResult> Create(SaveProcedureCategoryCommand command,CancellationToken c)=>(await mediator.Send(command,c)).ToActionResult(this);[HttpPut("{id:guid}")]public async Task<IActionResult> Update(Guid id,SaveProcedureCategoryRequest r,CancellationToken c)=>(await mediator.Send(new SaveProcedureCategoryCommand(id,r.Name,r.Description),c)).ToActionResult(this);[HttpPost("{id:guid}/ativar")]public async Task<IActionResult> Activate(Guid id,CancellationToken c)=>(await mediator.Send(new SetProcedureCategoryActiveCommand(id,true),c)).ToActionResult(this);[HttpPost("{id:guid}/inativar")]public async Task<IActionResult> Deactivate(Guid id,CancellationToken c)=>(await mediator.Send(new SetProcedureCategoryActiveCommand(id,false),c)).ToActionResult(this);public sealed record SaveProcedureCategoryRequest(string Name,string? Description);}
